<?php
declare(strict_types=1);
$root=dirname(__DIR__);$configFile=$root.'/config.php';if(is_file($configFile)){header('Location: ../');exit;}$error='';$appBase=rtrim(dirname($_SERVER['SCRIPT_NAME']??'/'),'/');if(basename($appBase)==='install')$appBase=rtrim(dirname($appBase),'/');
if($_SERVER['REQUEST_METHOD']==='POST'){
 $host=trim((string)($_POST['db_host']??'localhost'));$name=trim((string)($_POST['db_name']??''));$user=trim((string)($_POST['db_user']??''));$pass=(string)($_POST['db_pass']??'');$adminName=trim((string)($_POST['admin_name']??''));$email=trim((string)($_POST['admin_email']??''));$adminPass=(string)($_POST['admin_password']??'');$mode=(string)($_POST['business_mode']??'');
 try{
  if(!in_array($mode,['single_vendor','multi_vendor'],true))throw new RuntimeException('Geçerli bir işletme modeli seçin.');
  if(!$name||!$user||!$adminName||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($adminPass)<10)throw new RuntimeException('Zorunlu alanları doldurun. Yönetici şifresi en az 10 karakter olmalı.');
  $pdo=new PDO('mysql:host='.$host.';dbname='.$name.';charset=utf8mb4',$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
  $sql=[
  "CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'customer',status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
  "CREATE TABLE IF NOT EXISTS settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(190) NOT NULL UNIQUE,setting_value LONGTEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
  "CREATE TABLE IF NOT EXISTS menus(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,url VARCHAR(500) NOT NULL,location VARCHAR(50) NOT NULL DEFAULT 'header',sort_order INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
  "CREATE TABLE IF NOT EXISTS pages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,content LONGTEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
  "CREATE TABLE IF NOT EXISTS categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,description TEXT NULL,sort_order INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
  "CREATE TABLE IF NOT EXISTS products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,short_description TEXT NULL,description LONGTEXT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,image VARCHAR(500) NULL,delivery_type VARCHAR(30) NOT NULL DEFAULT 'manual',status VARCHAR(20) NOT NULL DEFAULT 'draft',sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_products_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
  "CREATE TABLE IF NOT EXISTS orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,order_no VARCHAR(50) NOT NULL UNIQUE,subtotal DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'pending',payment_status VARCHAR(30) NOT NULL DEFAULT 'unpaid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_orders_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
  "CREATE TABLE IF NOT EXISTS order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,seller_id BIGINT UNSIGNED NULL,seller_commission_rate DECIMAL(5,2) NOT NULL DEFAULT 10.00,product_name VARCHAR(190) NOT NULL,quantity INT NOT NULL DEFAULT 1,unit_price DECIMAL(12,2) NOT NULL,CONSTRAINT fk_items_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
  "CREATE TABLE IF NOT EXISTS payment_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,provider VARCHAR(30) NOT NULL,provider_reference VARCHAR(190) NULL,amount DECIMAL(12,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_payment_order FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
  ];
  if($mode==='multi_vendor'){$sql[]="CREATE TABLE IF NOT EXISTS seller_profiles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,shop_name VARCHAR(190) NOT NULL,shop_slug VARCHAR(190) NOT NULL UNIQUE,commission_rate DECIMAL(5,2) NOT NULL DEFAULT 10.00,status VARCHAR(20) NOT NULL DEFAULT 'pending',CONSTRAINT fk_seller_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";$sql[]="CREATE TABLE IF NOT EXISTS seller_ledger(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,seller_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,entry_type VARCHAR(30) NOT NULL,amount DECIMAL(12,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_ledger_seller FOREIGN KEY(seller_id) REFERENCES seller_profiles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";$sql[]="CREATE TABLE IF NOT EXISTS seller_profiles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,shop_name VARCHAR(190) NOT NULL,shop_slug VARCHAR(190) NOT NULL UNIQUE,commission_rate DECIMAL(5,2) NOT NULL DEFAULT 10.00,status VARCHAR(20) NOT NULL DEFAULT 'pending',CONSTRAINT fk_seller_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";}
  $pdo->beginTransaction();foreach($sql as $q)$pdo->exec($q);if($mode==='multi_vendor'){$check=$pdo->query("SHOW COLUMNS FROM products LIKE 'seller_id'");if(!$check->fetch())$pdo->exec('ALTER TABLE products ADD seller_id BIGINT UNSIGNED NULL, ADD CONSTRAINT fk_product_seller FOREIGN KEY(seller_id) REFERENCES seller_profiles(id) ON DELETE SET NULL');}
  $st=$pdo->prepare("INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),password_hash=VALUES(password_hash),role='admin',status='active'");$st->execute([$adminName,$email,password_hash($adminPass,PASSWORD_DEFAULT),'admin','active']);
  $defaults=['site_title'=>'E-pin Mağazası','home_heading'=>'Oyun dünyasına hızlı erişim','home_description'=>'Dijital oyun ürünlerini keşfedin.','footer_text'=>'','business_mode'=>$mode,'currency'=>'TRY','locale'=>'tr_TR'];$st=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($defaults as $k=>$v)$st->execute([$k,$v]);
  if(!is_dir($root.'/storage')&&!mkdir($root.'/storage',0755,true)&&!is_dir($root.'/storage'))throw new RuntimeException('storage klasörü oluşturulamadı.');$cfg="<?php\nreturn ".var_export(['db_host'=>$host,'db_name'=>$name,'db_user'=>$user,'db_pass'=>$pass,'business_mode'=>$mode,'app_key'=>bin2hex(random_bytes(32))],true).";\n";if(file_put_contents($configFile,$cfg,LOCK_EX)===false)throw new RuntimeException('config.php yazılamadı; ana klasör yazma iznini kontrol edin.');@chmod($configFile,0640);try{$pdo->commit();}catch(Throwable $commitError){@unlink($configFile);throw $commitError;}file_put_contents($root.'/storage/installed.lock',date(DATE_ATOM));header('Location: ../login');exit;
 }catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>E-pin kurulum</title><link rel="stylesheet" href="<?= htmlspecialchars(($appBase ?: '').'/assets/css/app.css', ENT_QUOTES, 'UTF-8') ?>"></head><body><main class="installer"><div class="installer-card"><p class="eyebrow">KURULUM SİHİRBAZI</p><h1>E-pin mağazanızı kurun</h1><p>Sunucu ve yönetici bilgilerini girerek kurulumu tarayıcıdan tamamlayın.</p><?php if($error): ?><div class="alert"><?= htmlspecialchars($error,ENT_QUOTES,'UTF-8') ?></div><?php endif; ?><form method="post"><h2>İşletme modeli</h2><label class="choice"><input type="radio" name="business_mode" value="single_vendor" checked><span><b>Single Vendor</b><small>Tek bir e-pin firmasının kendi satış mağazası.</small></span></label><label class="choice"><input type="radio" name="business_mode" value="multi_vendor"><span><b>Multi Vendor</b><small>Birden fazla satıcının mağaza açabildiği pazar yeri.</small></span></label><h2>Veritabanı</h2><label>Sunucu<input name="db_host" value="localhost" required></label><label>Veritabanı adı<input name="db_name" required></label><label>Veritabanı kullanıcı adı<input name="db_user" required></label><label>Veritabanı şifresi<input type="password" name="db_pass"></label><h2>Yönetici hesabı</h2><label>Ad soyad<input name="admin_name" required></label><label>E-posta<input type="email" name="admin_email" required></label><label>Şifre (en az 10 karakter)<input type="password" name="admin_password" minlength="10" required></label><button type="submit">Kurulumu başlat</button></form></div></main></body></html>
